import justPick from"just-pick";import*as apiMiddleware from"../../action/api-middleware.js";import*as userServer from"../../service/user.js";import*as tokenServer from"../../service/token.js";import*as userTools from"../../common/user-tools.js";import{PublicReturn}from"../../common/public-return.js";import*as uuidTools from"../../common/uuid-tools.js";import{getReqLimiter}from"../../action/req-limiter.js";import{userUpdateValidatorFn,userRegisterValidatorFn}from"../../action/verified-option.js";import{privateDecrypt}from"../../common/rsa-tools.js";import{getRandomElement}from"../../common/other-tools.js";export function createRouter(e){e.post("/user/register",{preHandler:[apiMiddleware.vCaptcha,getReqLimiter(1,3e3)]},async function(e,r){const t=justPick(e.body||{},["name","password"]);t.password=privateDecrypt(t.password||"");const o=userRegisterValidatorFn(t);if(o)return void r.code(400).send(new PublicReturn(400,o));if(await userServer.findByName(t.name))return void r.code(409).send(new PublicReturn(409,"注册失败: 用户名已被占用"));const n=getRandomElement([6,7,8,9,10,11]),s=(new Date).getTime(),i={uId:uuidTools.createUuid(),initDate:s,updateDate:s,name:t.name,role:"user",nickname:t.name,synopsis:"",avatar:"assets/public/user.jpg",about:"",password:userTools.hashPassword(t.password||"",n)},a=await userServer.add(i),d={uId:uuidTools.createUuid(),userUId:a.uId,userName:a.name,userRole:a.role,token:userTools.createToken()+"-|-"+a.uId,initDate:s};await tokenServer.add(d),r.send(new PublicReturn(200,"成功",d.token))}),e.post("/user/login",{preHandler:[apiMiddleware.vCaptcha,getReqLimiter(1,3e3)]},async function(e,r){const t=e.body||{};t.password=privateDecrypt(t.password||"");const o=await userServer.find(e=>e.name==t.name);if(!o)return void r.code(404).send(new PublicReturn(404,"没找到相应用户"));if(!userTools.comparePassword(t.password||"",o.password||""))return void r.code(400).send(new PublicReturn(400,"密码验证失败"));const n={uId:uuidTools.createUuid(),userUId:o.uId,userName:o.name,userRole:o.role,token:userTools.createToken()+"-|-"+o.uId,initDate:(new Date).getTime()};await tokenServer.add(n),r.send(new PublicReturn(200,"成功",n.token))}),e.get("/user/info",{preHandler:apiMiddleware.vToken},async function(e,r){const t=e.headers||{},o=(String(t.token)||"").split("-|-")[1],n=await userServer.find(e=>e.uId==o);if(!n)return void r.code(400).send(new PublicReturn(400,"没找到相应用户"));const s=await tokenServer.filter(e=>e.userUId==n.uId);n.tokenNumber=s.length,delete n.password,r.send(new PublicReturn(200,"成功",n))}),e.put("/user/update",{preHandler:[apiMiddleware.vToken,getReqLimiter(1,3e3)]},async function(e,r){const t=e.headers||{},o=(String(t.token)||"").split("-|-")[1],n=justPick(e.body||{},["uId","nickname","synopsis","avatar","about"]),s=userUpdateValidatorFn(n);if(s)return void r.code(400).send(new PublicReturn(400,s));if(o!=n.uId)return void r.code(400).send(new PublicReturn(400,"尝试修改其他用户数据"));const i=await userServer.find(e=>e.uId==o);i?(n.updateDate=(new Date).getTime(),await userServer.update(i,n),r.send(new PublicReturn(200,"修改成功",n))):r.code(404).send(new PublicReturn(404,"没找到相应用户"))}),e.post("/user/logout",{preHandler:apiMiddleware.vToken},async function(e,r){const t=e.body||{},o=e.headers||{},n=String(o.token)||"",s=n.split("-|-")[1],i=await tokenServer.allList(),a=await userServer.find(e=>e.uId==s);a?(!0===t.exitAll?await tokenServer.delete_(i):await tokenServer.delete_(i.filter(e=>e.userUId==a.uId&&e.token==n)),r.send(new PublicReturn(200,"成功"))):r.code(404).send(new PublicReturn(404,"没找到相应用户"))})}